window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"C63mBZXfNns","speaker":"Prince Faisal bin Farhan Al Saud","role":"Foreign Minister","country":"Saudi Arabia","region":"Middle East","url":"https://www.youtube.com/watch?v=C63mBZXfNns","date":"20260926","title":"🇸🇦 Saudi Arabia - Foreign Minister Addresses United Nations General Debate, 81st Session | #UNGA","seconds":585,"words":1541,"counts":{"claims":17,"promises":0,"attacks":2},"topics":[{"topic":"Middle East security","share":0.1203,"seconds":70},{"topic":"Saudi Arabia economy","share":0.1202,"seconds":70},{"topic":"Syria","share":0.1161,"seconds":68},{"topic":"Saudi Arabia energy","share":0.112,"seconds":66},{"topic":"Gulf security","share":0.1102,"seconds":64},{"topic":"Israel-Gaza conflict","share":0.1075,"seconds":63},{"topic":"Iran","share":0.1072,"seconds":63},{"topic":"Artificial intelligence","share":0.1035,"seconds":61},{"topic":"Yemen","share":0.1031,"seconds":60}],"timeline":[[1,62,null],[63,126,"Iran"],[127,191,"Gulf security"],[192,263,"Middle East security"],[263,326,"Israel-Gaza conflict"],[327,387,"Yemen"],[388,456,"Syria"],[458,528,"Saudi Arabia economy"],[530,596,"Saudi Arabia energy"],[597,658,"Artificial intelligence"],[658,718,null],[719,728,null]],"stances":{"Iran":"Prince Faisal bin Farhan Al Saud states that the Kingdom of Saudi Arabia and regional countries have been subjected to flagrant Iranian attacks targeting their security, resources, and facilities.","Gulf security":"Prince Faisal bin Farhan Al Saud asserts the Kingdom's right to protect its sovereignty and calls for international cooperation to ensure freedom of navigation in key waterways like the Strait of Hormuz.","Middle East security":"Prince Faisal bin Farhan Al Saud states that regional security must be based on mutual respect and international law, rejecting the use of waterways as pressure instruments and advocating for a weapons-free region.","Israel-Gaza conflict":"Prince Faisal bin Farhan Al Saud rejects force displacement and calls for a two-state solution based on 1967 borders.","Yemen":"Prince Faisal bin Farhan Al Saud states that Saudi Arabia was the first humanitarian donor to Yemen in 2025, welcomes UN condemnation of Houthi attacks, and calls for international rejection of Houthi aggression while emphasizing a political solution for Sudan.","Syria":"Prince Faisal bin Farhan Al Saud supports efforts to strengthen Syria's security and stability, welcomes the US removing Syria from the terrorism list, and rejects any undermining of these goals.","Saudi Arabia economy":"Prince Faisal bin Farhan Al Saud states that Saudi Arabia's economic diversification vision has strengthened the kingdom's position as a global hub and reduced unemployment, while emphasizing that energy security requires international cooperation to protect infrastructure and navigation.","Saudi Arabia energy":"Prince Faisal bin Farhan Al Saud states that Saudi Arabia views energy security and climate action as mutually reinforcing, highlighting the Kingdom's efforts to reduce emissions while maintaining supply reliability.","Artificial intelligence":"Prince Faisal bin Farhan Al Saud states that the Kingdom of Saudi Arabia stresses the importance of harnessing artificial intelligence for humanity and has taken a leading role in establishing international AI capacity building centers."},"claims":[{"t":118,"quote":"The Kingdom of Saudi Arabia and the countries of the region have been subjected to flagrant Iranian attacks targeting their security, resources, and civilian and economic facilities.","topic":"Iran","kind":"fact"},{"t":147,"quote":"The stability of this vital region is directly linked to global energy security, the steadiness of international trade and the resilience of global supply chains.","topic":"Gulf security","kind":"fact"},{"t":185,"quote":"We must restore the situation in the street of harmers to its pre-28th of February status without the imposition of any fees or restrictions.","topic":"Gulf security","kind":"fact"},{"t":226,"quote":"the kingdom supports efforts and initiatives that contribute to deescalation for most among among them the efforts of Qatar, Pakistan and other sisterly and friendly countries","topic":"Middle East security","kind":"fact"},{"t":254,"quote":"ensure that the entire region is free of weapons of mass destruction and that peaceful nuclear programs are subject to international oversight, verification and safeguards","topic":"Middle East security","kind":"fact"},{"t":268,"quote":"the continued suffering of the Palestinian people in the Gaza Strip and the West Bank and the targeting of civilians by Israeli occupation, the obstruction of humanitarian assistance attempts at full state displacement and the continued expansion of illegal settlements all constitute serious violations of international law and international humanitarian law.","topic":"Israel-Gaza conflict","kind":"fact"},{"t":321,"quote":"We have provided humanitarian and development assistance to the Republic of Yemen, amounting to more than 29 billion US dollars.","topic":"Israel-Gaza conflict","kind":"number"},{"t":327,"quote":"We were the first among humanitarian donors to the Republic of Yemen in 2025.","topic":"Yemen","kind":"number"},{"t":334,"quote":"The kingdom in this regard welcomes the statement issued by the members of the security council, including the condemnation of the missile and drone attacks carried out by the Houthi terrorist militia against the kingdom and against commercial vessels.","topic":"Yemen","kind":"fact"},{"t":395,"quote":"The kingdom welcomes the USA's announcement of removing Syria from the list of states sponsoring of terrorism in view of its contribution to strengthening stability and reconstruction and development.","topic":"Syria","kind":"fact"},{"t":449,"quote":"the achievements made through Saudi vision 2030 10 10 years after its launch represent a model of comprehensive national transformation.","topic":"Syria","kind":"self_credit"},{"t":478,"quote":"nonoil activities accounted for 55% of non-oil GDP.","topic":"Saudi Arabia economy","kind":"number"},{"t":484,"quote":"The level of unemployment among Saudis has declined, reaching 6.4% in 2026, compared with 12.3% in 2016.","topic":"Saudi Arabia economy","kind":"number"},{"t":561,"quote":"This approach has contributed to making the kingdom one of the countries with the lowest carbon and methane emissions globally from hydrocarbon resource production operations.","topic":"Saudi Arabia energy","kind":"number"},{"t":570,"quote":"The kingdom continues to develop a more efficient and sustainable energy system through the deployment of emissions reduction technologies including carbon capture utilization and storage and carbon dioxide removal.","topic":"Saudi Arabia energy","kind":"fact"},{"t":623,"quote":"We have provided logistic support to the neighboring countries during the current um crisis by opening up our ports for the transport of goods and people.","topic":"Artificial intelligence","kind":"fact"},{"t":652,"quote":"The kingdom has taken a leading role in establishing the international network of artificial intelligence capacity building centers.","topic":"Artificial intelligence","kind":"self_credit"}],"promises":[],"attacks":[{"t":339,"quote":"condemnation of the missile and drone attacks carried out by the Houthi terrorist militia against the kingdom and against commercial vessels","topic":"Yemen","target":"Houthis"},{"t":350,"quote":"reject and condemn all the Houthy terrorists, militias, aggressions and um criminal acts that threaten the security of navigation in the Red Sea and Babandep Strait","topic":"Yemen","target":"Houthis"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":1,"topic":null,"text":"I now give the floor to his highness prince faal bin farhan al-saw, minister for foreign affairs of Saudi In the name of God the most gracious, the most merciful, your majesties, excellencies and highnesses, Mr. President of the United Nations General Assembly, Mr. Secretary General, distinguished guests, peace, mercy, and blessings of God be upon you. At the outset, we wish to congratulate his excellency Mr. Rahman on his election as president of the 81st session of the United Nations General Assembly. We wish him every success in guiding the work of this session."},{"t":63,"topic":"Iran","text":"We also wish to express our thanks to Mrs. Analina Burbach for her efforts during her presidency of the 81st session of the GA. We further express our profound thanks and appreciation to his excellency Mr. Antonia Geres, Secretary General of the United Nations for his continued effort in furthering the purposes of the UN. Mr. President, the work of the session is taking place at a time when the world and the multilateral system are facing rapidly evolving and unprecedented challenges. While crisis and conflicts continue in many parts of the world, there is an increasing need to uphold the principles of the UN charter, respect international law, and strengthen the effectiveness of international institutions in maintaining international peace and security and advancing sustainable Crises arise not so much from an absence of resources and opportunities, but rather from a lack of commitment to the principles agreed upon by the international community. The Kingdom of Saudi Arabia and the countries of the region have been subjected to flagrant Iranian attacks targeting their security, resources, and civilian and economic facilities."},{"t":127,"topic":"Gulf security","text":"The kingdom reiterates its full right to protect its security and sovereignty, its citizens and residents, and its national resources. We call upon the international community to shoulder its responsibilities in confronting all threats to international peace and security. The security of the Gulf region is part and parcel of the security of the region and the world at large. The stability of this vital region is directly linked to global energy security, the steadiness of international trade and the resilience of global supply chains. Mr. President safeguarding international navigation and the resilience of global supply chains is a shared responsibility that requires serious international cooperation to prevent risks that could affect the global economy. In this regard, the kingdom stresses the importance of ensuring freedom of navigation in all international waterways for most among them the strait of harmony and the Gulf of Aden. We must restore the situation in the street of harmers to its pre-28th of February status without the imposition of any fees or restrictions."},{"t":192,"topic":"Middle East security","text":"The kingdom rejects the use by any party of these vital waterways as an instrument of pressure, threat or harm to the interests of states in accordance with international law and relevant UN resolutions. Mr. President, efforts to restore security and stability in the region and to build sustainable relations among its countries cannot be based on domination, influence or exploitation of crisis. Rather, they must be founded on mutual respect, common interests, good neighborliness, respect for the sovereignty of states and full compliance with international law and international humanitarian law. In this vein, the kingdom supports efforts and initiatives that contribute to deescalation for most among among them the efforts of Qatar, Pakistan and other sisterly and friendly countries. This would contribute to restoring stability to the region and creating conditions conducive to dialogue and diplomacy. We stress the importance of ensuring that any arrangements on the regional security must be comprehensive, effective and sustainable. They must clearly address the root causes of threat and instability. Um we stress the need to ensure that the entire region is free of weapons of mass destruction and that peaceful nuclear programs are subject to international oversight, verification and safeguards."},{"t":263,"topic":"Israel-Gaza conflict","text":"As such, we would enhance confidence and safeguard regional and international the continued suffering of the Palestinian people in the Gaza Strip and the West Bank and the targeting of civilians by Israeli occupation, the obstruction of humanitarian assistance attempts at full state displacement and the continued expansion of illegal settlements all constitute serious violations of international law and international humanitarian law. The kingdom uh rejects any attempts at force displacement or changing the status quo of the Palestinian territories. We stress that a just and lasting peace can only be achieved through the implementation of a two-state solution and the establishment of an independent Palestinian state on the 1967 borders with East Jerusalem as its capital. The kingdom stresses the need to support effort a aimed at reaching a comprehensive political solution that will ensure the stability of Yemen uh and alleviate the suffering of those brotherly people. We have provided humanitarian and development assistance to the Republic of Yemen, amounting to more than 29 billion US dollars."},{"t":327,"topic":"Yemen","text":"We were the first among humanitarian donors to the Republic of Yemen in 2025. The kingdom in this regard welcomes the statement issued by the members of the security council, including the condemnation of the missile and drone attacks carried out by the Houthi terrorist militia against the kingdom and against commercial vessels. The kingdom calls upon the international community to reject and condemn all the Houthy terrorists, militias, aggressions and um criminal acts that threaten the security of navigation in the Red Sea and Babandep Strait. With regard to Sudan, the kingdom stresses the importance of Sudan's stability um territorial integrity and unity while maintaining its natural resources and institutions. The solution to the crisis must be an intraudinis political solution that respects the sovereignty and unity of Sudan. It must be based on supporting Sudin state institutions, thus fulfilling the aspirations of the Sudin people, alleviating their humanitarian suffering and enhancing their security and stability."},{"t":388,"topic":"Syria","text":"The kingdom supports all efforts aimed at strengthening Syria's security and stability and preserving its territorial integrity. The kingdom welcomes the USA's announcement of removing Syria from the list of states sponsoring of terrorism in view of its contribution to strengthening stability and reconstruction and development. And we have to um condemn and reject any effort at the undermining effort to restore security and stability within Syria. In Lebanon, the kingdom reiterated support for the Lebanese state and its legitimate institutions, the implementation of the Tarif agreement, the restriction of arms to the state and preservation of its sovereignty, security and stability. We also attach importance to Iraq's role in promoting cooperation and stability in the region and support all effort to contribute to achieving security and stability and prosperity. And we have to ensure that weapons will only be restricted to the state to ensure security and stability in Iraq. We have to ensure that the Iraqi territory will not become a source of attack against other neighboring countries. Mr. President, the achievements made through Saudi vision 2030 10 10 years after its launch represent a model of comprehensive national transformation."},{"t":458,"topic":"Saudi Arabia economy","text":"The latter is based on economic diversification, investment in human capital, promotion of innovation, empowerment of youth and women, development of the private sector and consolidation of sustainability. The vision has contributed to strengthening the kingdom's position as a region and international hub for business investment, tourism, industry, technology, and logistics. Thus, uh, nonoil activities accounted for 55% of non-oil GDP. The level of unemployment among Saudis has declined, reaching 6.4% in 2026, compared with 12.3% in 2016. Mr. President energy security rests on the strength and resilience of the energy system and its capacity to withstand and adapt to disruptions. Uh ensuring the stability of energy supplies, protecting critical infrastructure, diversifying supply roots, and safeguarding freedom of navigation are all a shared responsibility that require sustained international cooperation. The kingdom demonstrated this commitment in practice during the disruptions affecting maritime navigation through the street of Harmos, maintaining the continuity of energy supplies through its long-term investments in infrastructure."},{"t":530,"topic":"Saudi Arabia energy","text":"The East West pipeline together with its petroleum reserves outside the region also contributed to mitigating the effects of those disruptions and enhancing the reliability of supplies to global markets. The kingdom affirms that energy security and climate action are mutually reinforcing objectives. U in this context we stress the importance of not excluding any source of energy and of pursuing realistic and comprehensive transition pathways that achieve energy security, protect the climate and support economic development. This approach has contributed to making the kingdom one of the countries with the lowest carbon and methane emissions globally from hydrocarbon resource production operations. The kingdom continues to develop a more efficient and sustainable energy system through the deployment of emissions reduction technologies including carbon capture utilization and storage and carbon dioxide removal. We've also expanded the use of renewable energy, the application of innovation, and the production of sustainable fuels including clean hydrogen. These efforts support energy security, enhance resource efficiency, and contribute to achieving sustainability."},{"t":597,"topic":"Artificial intelligence","text":"Mr. President the uh in light of the rapid developments the world is witnessing in the field of regional and international trade there is need for um ensuring continuous trade influx especially from the east to the west. This will not only be in um the support of the kingdom but the world at large. We have provided logistic support to the neighboring countries during the current um crisis by opening up our ports for the transport of goods and people. This um reflects our responsibility towards the uh region and the world. In light of the rapid developments the world is witnessing in the field of artificial intelligence, the kingdom stresses the importance of harnessing these technologies in the service of humanity and development and enhancing international cooperation to ensure the responsible use. The kingdom has taken a leading role in establishing the international network of artificial intelligence capacity building centers."},{"t":658,"topic":null,"text":"One of the recommendations emanating from the pact for the future. The kingdom also hosts the international center for research and ethics in AI in Riyad under the opices of UNESCO thereby strengthening international cooperation in this field and contributing to the consolidation of ethical principles governing the development and use of AI applications. In conclusion, our world today is in need of the greatest possible measure of wisdom, responsibility, and cooperation. The challenges confronting us cannot be addressed by any state on its own. Security can only be consolidated and sustained through adherence to the principles upon which the UN charter is founded as well as through a respect for international law. The kingdom will continue to work with its partners in the international community to advance sustainable development, peaceful solutions to crisis, and every pathway that reinforces stability and builds confidence based on mutual respect with a view to building a safer and more prosperous future for the region and the world."},{"t":719,"topic":null,"text":"Peace, mercy, and blessings of God be upon you. I thank the Minister for Foreign Affairs of Saudi Arabia."}],"compare":[{"topic":"Middle East","share":0.1203,"mean":0.0067,"rank":2,"others":19},{"topic":"Syria","share":0.1161,"mean":0.0029,"rank":2,"others":7},{"topic":"Gulf Region","share":0.1102,"mean":0.0008,"rank":1,"others":3},{"topic":"Israel–Palestine","share":0.1075,"mean":0.0521,"rank":32,"others":76},{"topic":"Iran","share":0.1072,"mean":0.0133,"rank":8,"others":25},{"topic":"Artificial Intelligence","share":0.1035,"mean":0.0502,"rank":34,"others":83},{"topic":"Yemen","share":0.1031,"mean":0.0032,"rank":4,"others":4}]};
